import java.util.*;

class Solution {
    public List<Integer> postorder(TreeNode root) {
        List<Integer> answer = new ArrayList<>();
        dfs(root, answer);
        return answer;
    }

    private void dfs(TreeNode node, List<Integer> answer) {
        if (node == null) {
            return;
        }
        dfs(node.left, answer);
        dfs(node.right, answer);
        answer.add(node.val);
    }
}
